using GraphApi.Models.FNZ.TiposMovimiento;namespace GraphApi.Services.FNZ.TiposMovimiento{    /// <summary>    /// Define las operaciones de negocio y persistencia para TiposMovimientos.    /// </summary>    public interface ITiposMovimientoService    {        /// <summary>        /// Obtiene la lista de TiposMovimientos con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadTiposMovimiento>> GetTiposMovimientos(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de TiposMovimientos con filtros opcionales.        /// </summary>        /// <param name="tipoMovimientoID">Filtro opcional para TipoMovimientoID.</param>        /// <param name="tipoMovimiento">Filtro opcional para TipoMovimiento.</param>        /// <param name="bCargo">Filtro opcional para bCargo.</param>        /// <param name="bAbono">Filtro opcional para bAbono.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetTiposMovimientosDynamic(            int? tipoMovimientoID,            string? tipoMovimiento,            bool? bCargo,            bool? bAbono,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo TiposMovimiento.        /// </summary>        /// <param name="objInput">Datos para crear el TiposMovimiento.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposMovimiento> CreateTiposMovimiento(            clCreateTiposMovimiento objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un TiposMovimiento.        /// </summary>        /// <param name="objInput">Datos para actualizar el TiposMovimiento, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTiposMovimiento?> UpdateTiposMovimiento(            clUpdateTiposMovimiento objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un TiposMovimiento por su ID.        /// </summary>        /// <param name="nTiposMovimientoID">ID del TiposMovimiento a eliminar.</param>        Task<bool> DeleteTiposMovimiento(int nTiposMovimientoID);    }}